pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {EtherLotto} from "../src/EtherLotto.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    EtherLotto c;

    function setUp() public {
        c = new EtherLotto();
    }

    function _run(uint256 amount) internal {
        amount = bound(amount, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        amount = bound(amount, 0, 1000000);
        vm.assume(address(this).balance >= amount);
        uint256 oldPot;
        try c.pot() returns (uint256 __r) { oldPot = __r; } catch { return; }
        uint oldBal = address(c).balance;
        bool reverted = true;
        try c.play{value: amount}() {} catch { return; }
        reverted = false;
        uint256 newPot;
        try c.pot() returns (uint256 __r) { newPot = __r; } catch { return; }
        assertTrue((amount != 10 wei && reverted && newPot == oldPot) || (amount == 10 wei && !reverted && (newPot == 0 || newPot == oldPot + 10 wei)));
    }

    function testFuzz_run(uint256 amount) public {
        _run(amount);
    }

    receive() external payable {}
}
